const router = Router();
function razorpayDiagnostic(marker, details = {}) {
  console.info(marker, JSON.stringify(details));
}
function validHmac(value, expected) {
  if (!value || !expected || value.length !== expected.length) return false;
  return crypto.timingSafeEqual(Buffer.from(value), Buffer.from(expected));
}

router.post('/payment/webhook', async (req, res, next) => {
  try {
    razorpayDiagnostic('[RAZORPAY_WEBHOOK]', { endpoint: '/api/payment/webhook', event: req.body?.event });
    if (!process.env.RAZORPAY_WEBHOOK_SECRET) return res.status(503).json({ message: 'Razorpay webhook is not configured' });
    const signature = req.get('x-razorpay-signature');
    const rawBody = Buffer.isBuffer(req.body) ? req.body : Buffer.from(JSON.stringify(req.body || {}));
    const expected = crypto.createHmac('sha256', process.env.RAZORPAY_WEBHOOK_SECRET).update(rawBody).digest('hex');
    if (!validHmac(signature, expected)) return res.status(400).json({ message: 'Invalid Razorpay webhook signature' });
    const payload = JSON.parse(rawBody.toString('utf8'));
    const event = payload.event;
    const entity = payload.payload?.payment?.entity;
    if (!entity?.id || !entity.order_id || !['payment.captured', 'payment.failed'].includes(event)) return res.sendStatus(200);
    const [payments] = await pool.query("SELECT id,order_id,status FROM payments WHERE provider='Razorpay' AND (provider_order_id=? OR provider_payment_id=?) ORDER BY id DESC LIMIT 1", [entity.order_id, entity.id]);
    if (!payments.length) return res.sendStatus(200);
    const captured = event === 'payment.captured';
    razorpayDiagnostic('[RAZORPAY_WEBHOOK]', { event, razorpayOrderId: entity.order_id, razorpayPaymentId: entity.id, paymentStatus: entity.status, amount: entity.amount, currency: entity.currency, matchedPayment: true, databasePaymentStatusBefore: payments[0].status });
    await tx(async (conn) => {
      const nextPaymentStatus = captured ? 'paid' : 'failed';
      if (payments[0].status === nextPaymentStatus) return;
      await conn.query("UPDATE payments SET provider_payment_id=?,status=?,raw_reference=?,captured_at=IF(?='paid',NOW(),captured_at),failed_at=IF(?='failed',NOW(),failed_at) WHERE id=?", [entity.id, nextPaymentStatus, JSON.stringify(entity), nextPaymentStatus, nextPaymentStatus, payments[0].id]);
      await conn.query('UPDATE orders SET payment_status=?,order_status=? WHERE id=? AND payment_status<>?', [captured ? 'Paid' : 'Failed', captured ? 'Processing' : 'Cancelled', payments[0].order_id, captured ? 'Paid' : 'Failed']);
      if (captured) await conn.query('INSERT IGNORE INTO invoices(order_id,invoice_number,invoice_reference) VALUES(?,?,?)', [payments[0].order_id, invoiceNumber(), `/api/admin/orders/${payments[0].order_id}/invoice`]);
      await conn.query('INSERT INTO order_status_history(order_id,new_status,note) VALUES(?,?,?)', [payments[0].order_id, captured ? 'Processing' : 'Cancelled', captured ? 'Razorpay payment captured and settled' : 'Razorpay payment failed']);
    });
    razorpayDiagnostic('[RAZORPAY_ORDER_UPDATE]', { source: 'webhook', internalOrderId: payments[0].order_id, paymentStatusAfter: captured ? 'Paid' : 'Failed', orderStatusAfter: captured ? 'Processing' : 'Cancelled' });
    if (captured) await notifyConfirmedOrder(payments[0].order_id, 'ONLINE');
    return res.sendStatus(200);
  } catch (error) { next(error); }
});
router.use((req, res, next) => {
  res.on('finish', () => {
    if (req.path === '/payments/razorpay/verify' && res.statusCode === 200 && req.body?.orderId) {
      razorpayDiagnostic('[RAZORPAY_INVOICE]', { internalOrderId: req.body.orderId, responseStatus: res.statusCode, action: 'create-or-reuse' });
      pool.query('INSERT IGNORE INTO invoices(order_id,invoice_number) VALUES(?,?)', [req.body.orderId, invoiceNumber()]).catch((error) => console.error('[Invoice]', error.message));
      razorpayDiagnostic('[RAZORPAY_EMAIL]', { internalOrderId: req.body.orderId, action: 'queue-confirmation' });
      notifyConfirmedOrder(req.body.orderId, 'ONLINE').catch((error) => console.error('[Order notification]', error.message));
    }
  });
  next();
});
router.use('/payments/razorpay/verify', (req, res, next) => {
  const callbackOrderId = req.body?.razorpayOrderId;
  const callbackPaymentId = req.body?.razorpayPaymentId;
  const signatureExpected = callbackOrderId && callbackPaymentId && process.env.RAZORPAY_KEY_SECRET
    ? crypto.createHmac('sha256', process.env.RAZORPAY_KEY_SECRET).update(`${callbackOrderId}|${callbackPaymentId}`).digest('hex')
    : null;
  razorpayDiagnostic('[RAZORPAY_SIGNATURE_VERIFY]', { internalOrderId: req.body?.orderId, razorpayOrderIdReceived: callbackOrderId, razorpayPaymentId: callbackPaymentId, signatureVerified: validHmac(req.body?.razorpaySignature, signatureExpected) });
  razorpayDiagnostic('[RAZORPAY_CHECKOUT_CALLBACK]', {
    endpoint: '/api/payments/razorpay/verify',
    internalOrderId: req.body?.orderId,
    razorpayOrderIdReceived: req.body?.razorpayOrderId,
    razorpayPaymentId: req.body?.razorpayPaymentId,
  });
  res.on('finish', async () => {
    razorpayDiagnostic('[RAZORPAY_VERIFY_RESPONSE]', { endpoint: '/api/payments/razorpay/verify', internalOrderId: req.body?.orderId, responseStatus: res.statusCode });
    if (!req.body?.orderId) return;
    try {
      const [[state]] = await pool.query('SELECT o.payment_status,o.order_status,p.provider_order_id,p.provider_payment_id,p.status FROM orders o LEFT JOIN payments p ON p.order_id=o.id AND p.provider=\'Razorpay\' WHERE o.id=? ORDER BY p.id DESC LIMIT 1', [req.body.orderId]);
      razorpayDiagnostic('[RAZORPAY_ORDER_UPDATE]', { internalOrderId: req.body.orderId, storedRazorpayOrderId: state?.provider_order_id, razorpayPaymentId: state?.provider_payment_id, databasePaymentStatusAfter: state?.payment_status, databaseOrderStatusAfter: state?.order_status, paymentRecordStatusAfter: state?.status });
    } catch (error) { console.error('[RAZORPAY_ORDER_UPDATE]', error.message); }
  });
  next();
});
router.post('/payments/razorpay/authorize-legacy', requireAuth, async (req, res, next) => {
  const { orderId: bodyOrderId, order_id: snakeOrderId, razorpayOrderId: bodyRazorpayOrderId, razorpay_order_id: snakeRazorpayOrderId, razorpayPaymentId: bodyRazorpayPaymentId, razorpay_payment_id: snakeRazorpayPaymentId, razorpaySignature: bodyRazorpaySignature, razorpay_signature: snakeRazorpaySignature } = req.body || {};
  if (bodyOrderId || snakeOrderId) {
    try {
      const orderId = bodyOrderId || snakeOrderId;
      const razorpayPaymentId = bodyRazorpayPaymentId || snakeRazorpayPaymentId;
      const razorpaySignature = bodyRazorpaySignature || snakeRazorpaySignature;
      const [[order]] = await pool.query('SELECT id,payment_status FROM orders WHERE id=? AND user_id=? LIMIT 1', [orderId, req.user.id]);
      const [[payment]] = await pool.query("SELECT provider_order_id FROM payments WHERE order_id=? AND provider='Razorpay' ORDER BY id DESC LIMIT 1", [orderId]);
      if (!order || !payment?.provider_order_id) return res.status(404).json({ message: 'Payment order record was not found' });
      if (order.payment_status === 'Paid' || order.payment_status === 'Authorized') return res.json({ message: 'Payment already confirmed', orderId, status: order.payment_status });
      const razorpayOrderId = bodyRazorpayOrderId || snakeRazorpayOrderId || payment.provider_order_id;
      if (razorpayOrderId !== payment.provider_order_id || !razorpayPaymentId || !process.env.RAZORPAY_KEY_SECRET) return res.status(400).json({ message: 'Invalid Razorpay payment details' });
      const expected = crypto.createHmac('sha256', process.env.RAZORPAY_KEY_SECRET).update(`${razorpayOrderId}|${razorpayPaymentId}`).digest('hex');
      if (!validHmac(razorpaySignature, expected)) return res.status(400).json({ message: 'Razorpay signature mismatch. Payment was not confirmed.' });
      await tx(async (conn) => {
        await conn.query("UPDATE payments SET provider_payment_id=?,status='authorized',raw_reference=? WHERE order_id=? AND provider='Razorpay'", [razorpayPaymentId, JSON.stringify(req.body), orderId]);
        await conn.query("UPDATE orders SET payment_status='Authorized',order_status='Processing' WHERE id=? AND payment_status='Pending'", [orderId]);
        await conn.query("INSERT INTO order_status_history(order_id,new_status,note,changed_by) VALUES(?,?,?,?)", [orderId, 'Processing', 'Razorpay payment authorized and confirmed', req.user.id]);
      });
      return res.json({ message: 'Payment authorized and order confirmed', orderId, status: 'Authorized' });
    } catch (error) { return next(error); }
  }
  try {
    const { orderId, razorpayOrderId, razorpayPaymentId, razorpaySignature } = req.body;
    if (!orderId || !razorpayPaymentId) return next();
    const [[order]] = await pool.query('SELECT id,total,payment_status FROM orders WHERE id=? AND user_id=? LIMIT 1', [orderId, req.user.id]);
    const [[paymentRecord]] = await pool.query("SELECT provider_order_id FROM payments WHERE order_id=? AND provider='Razorpay' ORDER BY id DESC LIMIT 1", [orderId]);
    if (!order || !paymentRecord?.provider_order_id) return res.status(404).json({ message: 'Payment order record was not found' });
    if (order.payment_status === 'Paid') return res.json({ message: 'Payment already verified', orderId });
    const providerOrderId = paymentRecord.provider_order_id;
    if (razorpayOrderId && razorpayOrderId !== providerOrderId) return res.status(400).json({ message: 'This payment does not belong to the selected order' });
    const expected = crypto.createHmac('sha256', process.env.RAZORPAY_KEY_SECRET).update(`${providerOrderId}|${razorpayPaymentId}`).digest('hex');
    if (!razorpaySignature || expected.length !== razorpaySignature.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(razorpaySignature))) return res.status(400).json({ message: 'Razorpay signature mismatch. The payment was not confirmed for this order.' });
    const auth = Buffer.from(`${process.env.RAZORPAY_KEY_ID}:${process.env.RAZORPAY_KEY_SECRET}`).toString('base64');
    const response = await fetch(`https://api.razorpay.com/v1/payments/${encodeURIComponent(razorpayPaymentId)}`, { headers: { Authorization: `Basic ${auth}` } });
    const providerPayment = await response.json();
    if (!response.ok) return res.status(502).json({ message: `Razorpay payment lookup failed: ${providerPayment.error?.description || 'provider returned an error'}` });
    if (providerPayment.order_id && providerPayment.order_id !== providerOrderId) return res.status(400).json({ message: 'The Razorpay payment was created for a different order.' });
    if (Number(providerPayment.amount) !== Math.round(Number(order.total) * 100) || providerPayment.currency !== 'INR') return res.status(400).json({ message: 'Razorpay payment details do not match this order.' });
    if (providerPayment.status !== 'captured') return res.status(409).json({ message: `Payment is ${providerPayment.status}. The order will be dispatched after Razorpay marks it captured.` });
    await tx(async (conn) => {
      await conn.query("UPDATE payments SET provider_payment_id=?,status='paid',raw_reference=? WHERE order_id=? AND provider='Razorpay'", [razorpayPaymentId, JSON.stringify(providerPayment), orderId]);
      await conn.query("UPDATE orders SET payment_status='Paid',order_status='Processing' WHERE id=? AND payment_status<>'Paid'", [orderId]);
      await conn.query("INSERT IGNORE INTO invoices(order_id,invoice_number) VALUES(?,?)", [orderId, invoiceNumber()]);
      await conn.query("INSERT INTO order_status_history(order_id,new_status,note,changed_by) VALUES(?,?,?,?)", [orderId, 'Processing', 'Razorpay payment captured and verified', req.user.id]);
    });
    return res.json({ message: 'Payment verified and order placed', orderId, status: 'Paid' });
  } catch (error) { next(error); }
});
