router.post('/payments/razorpay/order',requireAuth,async(req,res,next)=>{try{const [[existing]]=await pool.query("SELECT provider_order_id,raw_reference FROM payments WHERE order_id=? AND provider='Razorpay' AND status IN ('created','pending') ORDER BY id DESC LIMIT 1",[req.body.orderId]);if(existing?.provider_order_id){let order;try{order=JSON.parse(existing.raw_reference||'{}')}catch{}if(order?.id===existing.provider_order_id)return res.json({keyId:process.env.RAZORPAY_KEY_ID,order});}next();}catch(e){next(e)}});
const uploadDir = path.resolve(process.env.UPLOAD_DIR || '../uploads');
await fs.mkdir(uploadDir,{recursive:true});
const storage = multer.diskStorage({destination:uploadDir,filename:(_,file,cb)=>cb(null,`${Date.now()}-${file.originalname.replace(/[^a-zA-Z0-9._-]/g,'_')}`)});
const upload = multer({storage,limits:{fileSize:5*1024*1024},fileFilter:(_,file,cb)=>cb(null,/^(image\/(jpeg|png|webp|gif)|video\/(mp4|webm|ogg)|application\/pdf)$/.test(file.mimetype))});
function productVariants(product){return (product.variants||[]).filter(v=>v.size&&v.color).map((v,i)=>({...v,sku:v.sku||`${product.sku}-${i+1}`}));}
function productImages(product){return (product.images||[]).filter(image=>image.imageUrl);}
router.use('/admin/products', (req,res,next)=>{if(req.body&&['POST','PUT'].includes(req.method))req.body={...req.body,images:productImages(req.body),variants:productVariants(req.body)};next();});

async function userById(id){ const [r]=await pool.query('SELECT * FROM users WHERE id=? LIMIT 1',[id]); return r[0]; }

router.post('/auth/register', async (req,res,next)=>{try{const data=registerSchema.parse(req.body);const [dupe]=await pool.query('SELECT id FROM users WHERE email=?',[data.email]);if(dupe.length)return res.status(409).json({message:'Email is already registered'});const h=await hashPassword(data.password);const [r]=await pool.query(`INSERT INTO users(full_name,email,mobile,password_hash,role,date_of_birth,gender,address,city,state,postal_code,country,email_verified) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0)`,[data.fullName,data.email,data.mobile,h,'USER',data.dateOfBirth||null,data.gender||null,data.address,data.city,data.state,data.postalCode,data.country]);const u=await userById(r.insertId);setAuthCookie(res,signToken(u));res.status(201).json({user:publicUser(u)});}catch(e){next(e)}});
router.post('/auth/login', async (req,res,next)=>{try{const data=loginSchema.parse(req.body);const [r]=await pool.query('SELECT * FROM users WHERE email=? LIMIT 1',[data.email]);if(!r.length||!r[0].is_active)return res.status(401).json({message:'Invalid credentials'});if(!(await comparePassword(data.password,r[0].password_hash)))return res.status(401).json({message:'Invalid credentials'});setAuthCookie(res,signToken(r[0]));res.json({user:publicUser(r[0])});}catch(e){next(e)}});
router.post('/auth/logout',(req,res)=>{clearAuthCookie(res);res.json({message:'Logged out'})});
router.get('/auth/me',requireAuth,async(req,res,next)=>{try{const u=await userById(req.user.id);res.json({user:publicUser(u)});}catch(e){next(e)}});
router.post('/auth/forgot-password', async (req,res,next)=>{try{const email=String(req.body.email||'').toLowerCase();const [r]=await pool.query('SELECT id FROM users WHERE email=? AND is_active=1 LIMIT 1',[email]);const response={message:'If the account exists, password reset instructions will be sent.'};if(r.length){const raw=crypto.randomBytes(32).toString('hex');const hash=crypto.createHash('sha256').update(raw).digest('hex');await pool.query('DELETE FROM password_reset_tokens WHERE user_id=?',[r[0].id]);await pool.query('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))',[r[0].id,hash]);if(process.env.NODE_ENV!=='production')response.devResetToken=raw;}res.json(response);}catch(e){next(e)}});
router.post('/auth/reset-password', async(req,res,next)=>{try{const {token,newPassword}=req.body;if(!token||!newPassword||String(newPassword).length<8)return res.status(400).json({message:'Token and a password of at least 8 characters are required'});const hash=crypto.createHash('sha256').update(token).digest('hex');const [r]=await pool.query('SELECT * FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1',[hash]);if(!r.length)return res.status(400).json({message:'Reset link is invalid or expired'});await pool.query('UPDATE users SET password_hash=? WHERE id=?',[await hashPassword(newPassword),r[0].user_id]);await pool.query('UPDATE password_reset_tokens SET used_at=NOW() WHERE id=?',[r[0].id]);res.json({message:'Password reset successfully'});}catch(e){next(e)}});
router.post('/auth/change-password',requireAuth,async(req,res,next)=>{try{const {currentPassword,newPassword}=req.body;if(!newPassword||String(newPassword).length<8)return res.status(400).json({message:'New password must be at least 8 characters'});const u=await userById(req.user.id);if(!(await comparePassword(currentPassword,u.password_hash)))return res.status(400).json({message:'Current password is incorrect'});await pool.query('UPDATE users SET password_hash=? WHERE id=?',[await hashPassword(newPassword),u.id]);res.json({message:'Password changed'});}catch(e){next(e)}});

router.get('/home',async(_,res,next)=>{try{const [[slides],[sections],[banners],[videos],[reviews],[categories],[newArrivals],[bestSellers],[featured]] = await Promise.all([
  pool.query('SELECT * FROM carousel_slides WHERE is_active=1 ORDER BY display_order,id'),
  pool.query('SELECT * FROM homepage_sections WHERE is_active=1 ORDER BY display_order,id'),
  pool.query('SELECT * FROM promotional_banners WHERE is_active=1 ORDER BY display_order,id'),
  pool.query('SELECT * FROM fashion_videos WHERE is_active=1 ORDER BY display_order,id'),
  pool.query("SELECT * FROM reviews WHERE status='Approved' ORDER BY display_order,id LIMIT 12"),
  pool.query("SELECT * FROM categories WHERE is_active=1 AND name<>'' AND image_url IS NOT NULL AND image_url<>'' ORDER BY display_order,id"),
  pool.query('SELECT p.*,c.name category_name,(SELECT image_url FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.display_order,pi.id LIMIT 1) image_url,(SELECT image_url FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.display_order,pi.id LIMIT 1 OFFSET 1) hover_image_url FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1 AND p.new_arrival=1 ORDER BY p.display_order,p.id DESC LIMIT 8'),
  pool.query('SELECT p.*,c.name category_name,(SELECT image_url FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.display_order,pi.id LIMIT 1) image_url FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1 AND p.best_seller=1 ORDER BY p.display_order,p.id DESC LIMIT 8'),
  pool.query('SELECT p.*,c.name category_name,(SELECT image_url FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.display_order,pi.id LIMIT 1) image_url FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1 AND p.featured=1 ORDER BY p.display_order,p.id DESC LIMIT 8')
]);res.json({slides,sections,banners,videos,reviews,categories,newArrivals,bestSellers,featured});}catch(e){next(e)}});
router.get('/store-settings',async(_,res,next)=>{try{const [rows]=await pool.query("SELECT `key`,`value` FROM store_settings WHERE `key` IN ('shipping_flat_rate','free_shipping_threshold','cod_enabled','online_payment_enabled','delivery_estimate','about_title','about_content','about_image','contact_business_name','contact_phone','contact_email','contact_whatsapp','contact_address','contact_city','contact_state','contact_country','contact_postal_code','contact_hours','contact_social_links')");res.json({settings:Object.fromEntries(rows.map((row)=>[row.key,row.value]))});}catch(e){next(e)}});

router.get('/categories',async(_,res,next)=>{try{const [r]=await pool.query('SELECT * FROM categories WHERE is_active=1 ORDER BY display_order,id');res.json({categories:r})}catch(e){next(e)}});
router.get('/products',async(req,res,next)=>{try{const {q,category,minPrice,maxPrice,size,color,newArrival,bestSeller,offer,sort='newest'}=req.query;let sql=`SELECT p.*,c.name category_name,(SELECT image_url FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.display_order,pi.id LIMIT 1) image_url FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1`;const params=[];if(q){sql+=' AND (p.name LIKE ? OR p.short_description LIKE ? OR p.sku LIKE ?)';const x=`%${q}%`;params.push(x,x,x)}if(category){sql+=' AND c.slug=?';params.push(category)}if(minPrice){sql+=' AND COALESCE(p.sale_price,p.price)>=?';params.push(Number(minPrice))}if(maxPrice){sql+=' AND COALESCE(p.sale_price,p.price)<=?';params.push(Number(maxPrice))}if(newArrival==='1')sql+=' AND p.new_arrival=1';if(bestSeller==='1')sql+=' AND p.best_seller=1';if(offer==='1')sql+=' AND p.offer=1';if(size||color){sql+=` AND EXISTS (SELECT 1 FROM product_variants v WHERE v.product_id=p.id AND v.active=1 ${size?'AND v.size=?':''} ${color?'AND v.color=?':''})`;if(size)params.push(size);if(color)params.push(color);}const order=sort==='price-low'?'COALESCE(p.sale_price,p.price) ASC':sort==='price-high'?'COALESCE(p.sale_price,p.price) DESC':sort==='popular'?'p.best_seller DESC,p.id DESC':'p.id DESC';sql+=` ORDER BY ${order}`;const [r]=await pool.query(sql,params);res.json({products:r});}catch(e){next(e)}});
router.get('/products/:slug',async(req,res,next)=>{try{const [p]=await pool.query('SELECT p.*,c.name category_name,c.slug category_slug FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.active=1 LIMIT 1',[req.params.slug]);if(!p.length)return res.status(404).json({message:'Product not found'});const [images]=await pool.query('SELECT * FROM product_images WHERE product_id=? ORDER BY display_order,id',[p[0].id]);const [variants]=await pool.query('SELECT * FROM product_variants WHERE product_id=? AND active=1 ORDER BY id',[p[0].id]);const [related]=await pool.query('SELECT p.*, (SELECT image_url FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.display_order,pi.id LIMIT 1) image_url FROM products p WHERE p.active=1 AND p.category_id=? AND p.id<>? ORDER BY p.id DESC LIMIT 4',[p[0].category_id,p[0].id]);res.json({product:p[0],images,variants,related});}catch(e){next(e)}});

