router.put('/me/profile',requireAuth,async(req,res,next)=>{try{const {fullName,mobile,dateOfBirth,gender,address,city,state,postalCode,country}=req.body;await pool.query('UPDATE users SET full_name=?,mobile=?,date_of_birth=?,gender=?,address=?,city=?,state=?,postal_code=?,country=? WHERE id=?',[fullName,mobile,dateOfBirth||null,gender||null,address,city,state,postalCode,country,req.user.id]);const u=await userById(req.user.id);res.json({user:publicUser(u)});}catch(e){next(e)}});
router.get('/me/applications',requireAuth,async(req,res,next)=>{try{const [r]=await pool.query('SELECT * FROM applications WHERE user_id=? ORDER BY created_at DESC',[req.user.id]);res.json({applications:r})}catch(e){next(e)}});
router.post('/me/applications',requireAuth,upload.single('upload'),async(req,res,next)=>{try{const data=applicationSchema.parse({...req.body,termsAccepted:req.body.termsAccepted==='true'||req.body.termsAccepted===true});const code=applicationCode();const url=req.file?`/uploads/${req.file.filename}`:null;const [r]=await pool.query(`INSERT INTO applications(application_code,user_id,full_name,email,mobile,date_of_birth,gender,address,city,state,postal_code,country,preferred_category,preferred_size,preferred_contact_method,social_media,additional_message,upload_url) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,[code,req.user.id,data.fullName,data.email,data.mobile,data.dateOfBirth||null,data.gender||null,data.address,data.city,data.state,data.postalCode,data.country,data.preferredCategory||null,data.preferredSize||null,data.preferredContactMethod||null,data.socialMedia||null,data.additionalMessage||null,url]);await pool.query('INSERT INTO application_history(application_id,new_status,comment,changed_by) VALUES(?,?,?,?)',[r.insertId,'Submitted','Application submitted',req.user.id]);res.status(201).json({applicationCode:code,message:'Application submitted successfully'});}catch(e){next(e)}});
router.post('/me/applications/:id/additional-info',requireAuth,async(req,res,next)=>{try{const {additionalMessage}=req.body;const [a]=await pool.query("SELECT * FROM applications WHERE id=? AND user_id=? AND status='More Information Required'",[req.params.id,req.user.id]);if(!a.length)return res.status(404).json({message:'Application not found or additional information is not requested'});await pool.query('UPDATE applications SET additional_message=?,status=? WHERE id=?',['Updated by customer: '+additionalMessage,'Under Review',a[0].id]);await pool.query('INSERT INTO application_history(application_id,previous_status,new_status,comment,changed_by) VALUES(?,?,?,?,?)',[a[0].id,a[0].status,'Under Review','Customer supplied additional information',req.user.id]);res.json({message:'Additional information submitted'});}catch(e){next(e)}});
router.get('/me/orders',requireAuth,async(req,res,next)=>{try{const [orders]=await pool.query('SELECT * FROM orders WHERE user_id=? AND user_hidden_at IS NULL ORDER BY created_at DESC',[req.user.id]);for(const o of orders){const [items]=await pool.query('SELECT oi.*,(SELECT image_url FROM product_images pi WHERE pi.product_id=oi.product_id ORDER BY pi.display_order,pi.id LIMIT 1) image_url FROM order_items oi WHERE oi.order_id=? ORDER BY oi.id',[o.id]);o.items=items;}res.json({orders})}catch(e){next(e)}});
router.get('/me/orders/:id',requireAuth,async(req,res,next)=>{try{const [orders]=await pool.query('SELECT * FROM orders WHERE id=? AND user_id=? LIMIT 1',[req.params.id,req.user.id]);if(!orders.length)return res.status(404).json({message:'Order not found'});const [items]=await pool.query('SELECT oi.*,(SELECT image_url FROM product_images pi WHERE pi.product_id=oi.product_id ORDER BY pi.display_order,pi.id LIMIT 1) image_url FROM order_items oi WHERE oi.order_id=? ORDER BY oi.id',[orders[0].id]);orders[0].items=items;res.json({order:orders[0]});}catch(e){next(e)}});
async function sendInvoice(req,res,next,admin=false){try{const sql=admin?'SELECT o.*,u.full_name customer_name,u.email customer_email,u.mobile customer_mobile,i.invoice_number FROM orders o JOIN users u ON u.id=o.user_id LEFT JOIN invoices i ON i.order_id=o.id WHERE o.id=? LIMIT 1':'SELECT o.*,u.full_name customer_name,u.email customer_email,u.mobile customer_mobile,i.invoice_number FROM orders o JOIN users u ON u.id=o.user_id LEFT JOIN invoices i ON i.order_id=o.id WHERE o.id=? AND o.user_id=? LIMIT 1';const [orders]=await pool.query(sql,admin?[req.params.id]:[req.params.id,req.user.id]);if(!orders.length)return res.status(404).json({message:'Invoice not found'});const order=orders[0];if(!order.invoice_number)return res.status(409).json({message:'Invoice is not available until the order is confirmed'});const [items]=await pool.query('SELECT * FROM order_items WHERE order_id=? ORDER BY id',[order.id]);const rows=items.map((item)=>`<tr><td>${item.product_name}</td><td>${item.sku||''}</td><td>${item.size||''} / ${item.color||''}</td><td>${item.quantity}</td><td>INR ${Number(item.unit_price).toLocaleString('en-IN')}</td><td>INR ${Number(item.subtotal).toLocaleString('en-IN')}</td></tr>`).join('');const paymentMethod=order.payment_method==='COD'?'Cash on Delivery':'Razorpay';const paymentStatus=order.payment_method==='COD'?'COD Pending':order.payment_status;const html=`<!doctype html><html><head><meta charset="utf-8"><title>${order.invoice_number}</title><style>body{font-family:Arial,sans-serif;color:#222;margin:40px}header{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:16px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border-bottom:1px solid #ddd;padding:10px;text-align:left}tfoot td{font-weight:bold}</style></head><body><header><div><h1>CURVE BOUTIQUE</h1><p>Invoice ${order.invoice_number}</p></div><div><p>Order: ${order.order_code}</p><p>Date: ${new Date(order.created_at).toLocaleString('en-IN')}</p></div></header><h3>Customer</h3><p>${order.customer_name}<br>${order.customer_email}<br>${order.customer_mobile||''}</p><p>Shipping: ${order.shipping_name}, ${order.shipping_address}, ${order.shipping_city}, ${order.shipping_state}, ${order.shipping_postal_code}, ${order.shipping_country}</p><table><thead><tr><th>Product</th><th>SKU</th><th>Variant</th><th>Qty</th><th>Unit</th><th>Subtotal</th></tr></thead><tbody>${rows}</tbody><tfoot><tr><td colspan="5">Subtotal</td><td>INR ${Number(order.subtotal).toLocaleString('en-IN')}</td></tr><tr><td colspan="5">Discount</td><td>INR ${Number(order.discount).toLocaleString('en-IN')}</td></tr><tr><td colspan="5">Shipping</td><td>INR ${Number(order.shipping).toLocaleString('en-IN')}</td></tr><tr><td colspan="5">Total</td><td>INR ${Number(order.total).toLocaleString('en-IN')}</td></tr></tfoot></table><p>Payment method: ${paymentMethod}<br>Payment status: ${paymentStatus}<br>Order status: ${order.order_status}</p></body></html>`;res.setHeader('Content-Type','text/html; charset=utf-8');res.setHeader('Content-Disposition',`attachment; filename=${order.invoice_number}.html`);res.send(html);}catch(e){next(e)}}
router.get('/me/orders/:id/invoice',requireAuth,(req,res,next)=>sendInvoice(req,res,next));
router.delete('/me/orders/:id',requireAuth,async(req,res,next)=>{try{const [result]=await pool.query("UPDATE orders SET user_hidden_at=NOW() WHERE id=? AND user_id=? AND order_status='Cancelled'",[req.params.id,req.user.id]);if(!result.affectedRows)return res.status(400).json({message:'Only cancelled orders can be removed'});res.json({message:'Cancelled order removed from your order history'});}catch(e){next(e)}});
router.post('/payments/:orderId/cancel',requireAuth,async(req,res,next)=>{try{const result=await tx(async(conn)=>{const [[order]]=await conn.query("SELECT * FROM orders WHERE id=? AND user_id=? FOR UPDATE",[req.params.orderId,req.user.id]);if(!order)return null;if(order.payment_status!=='Pending')return {status:order.payment_status};await conn.query("UPDATE payments SET status='cancelled',raw_reference=? WHERE order_id=? AND status NOT IN ('paid','captured')",[JSON.stringify({reason:req.body?.reason||'cancelled'}),order.id]);const [items]=await conn.query('SELECT variant_id,quantity FROM order_items WHERE order_id=?',[order.id]);for(const item of items)if(item.variant_id)await conn.query('UPDATE product_variants SET stock_quantity=stock_quantity+? WHERE id=?',[item.quantity,item.variant_id]);await conn.query("UPDATE orders SET payment_status='Failed',order_status='Cancelled' WHERE id=? AND payment_status='Pending'",[order.id]);await conn.query("INSERT INTO order_status_history(order_id,previous_status,new_status,note,changed_by) VALUES(?,?,?,?,?)",[order.id,order.order_status,'Cancelled',req.body?.reason||'Payment cancelled',req.user.id]);return {status:'Cancelled'};});if(!result)return res.status(404).json({message:'Order not found'});res.json({message:'Payment cancelled',...result});}catch(e){next(e)}});
router.post('/payments/cod/:orderId',requireAuth,async(req,res,next)=>{try{const result=await tx(async(conn)=>{const [[order]]=await conn.query("SELECT * FROM orders WHERE id=? AND user_id=? FOR UPDATE",[req.params.orderId,req.user.id]);if(!order)return null;if(order.payment_status!=='Pending')return {status:order.payment_status};const [settings]=await conn.query("SELECT `key`,`value` FROM store_settings WHERE `key` IN ('cod_enabled')");const enabled=Object.fromEntries(settings.map((row)=>[row.key,row.value]));if(enabled.cod_enabled!=='1')throw Object.assign(new Error('Cash on Delivery is currently unavailable'),{status:400});const [[payment]]=await conn.query("SELECT id FROM payments WHERE order_id=? AND provider='COD' LIMIT 1",[order.id]);if(!payment)await conn.query("INSERT INTO payments(order_id,provider,amount,status) VALUES(?,?,?,'cod_pending')",[order.id,'COD',order.total]);await conn.query("UPDATE orders SET payment_method='COD',order_status='Processing' WHERE id=? AND payment_status='Pending'",[order.id]);if(order.order_status!=='Processing')await conn.query("INSERT INTO order_status_history(order_id,previous_status,new_status,note,changed_by) VALUES(?,?,?,?,?)",[order.id,order.order_status,'Processing','Cash on Delivery order confirmed',req.user.id]);await conn.query("INSERT IGNORE INTO invoices(order_id,invoice_number,invoice_reference) VALUES(?,?,?)",[order.id,invoiceNumber(),`/api/me/orders/${order.id}/invoice`]);return {status:'Processing',confirmed:!payment};});if(!result)return res.status(404).json({message:'Order not found'});if(result.confirmed)await notifyConfirmedOrder(req.params.orderId,'COD');res.json({message:'Cash on Delivery selected',...result});}catch(e){next(e)}});
router.post('/payments/razorpay/order',requireAuth,async(req,res,next)=>{try{const internalOrderId=req.body?.orderId;razorpayDiagnostic('[RAZORPAY_CREATE_ORDER]',{endpoint:'/api/payments/razorpay/order',internalOrderId});if(!process.env.RAZORPAY_KEY_ID||!process.env.RAZORPAY_KEY_SECRET)return res.status(503).json({message:'Online payment is not configured. Add Razorpay keys to server/.env.'});const [orders]=await pool.query("SELECT * FROM orders WHERE id=? AND user_id=? AND payment_status='Pending' LIMIT 1",[internalOrderId,req.user.id]);if(!orders.length)return res.status(404).json({message:'Pending order not found'});const auth=Buffer.from(`${process.env.RAZORPAY_KEY_ID}:${process.env.RAZORPAY_KEY_SECRET}`).toString('base64');const response=await fetch('https://api.razorpay.com/v1/orders',{method:'POST',headers:{Authorization:`Basic ${auth}`,'Content-Type':'application/json'},body:JSON.stringify({amount:Math.round(Number(orders[0].total)*100),currency:'INR',receipt:orders[0].order_code,payment_capture:1})});const razorpayOrder=await response.json();razorpayDiagnostic('[RAZORPAY_CREATE_ORDER]',{endpoint:'/api/payments/razorpay/order',internalOrderId,razorpayOrderId:razorpayOrder.id,responseStatus:response.status,amount:razorpayOrder.amount,currency:razorpayOrder.currency});if(response.status===401)return res.status(503).json({message:'Razorpay authentication failed. Replace RAZORPAY_KEY_ID and RAZORPAY_KEY_SECRET in server/.env with matching API keys.'});if(!response.ok)throw Object.assign(new Error(razorpayOrder.error?.description||'Unable to create online payment'),{status:502});await pool.query("INSERT INTO payments(order_id,provider,provider_order_id,amount,status,raw_reference) VALUES(?,?,?,?,?,?)",[internalOrderId,'Razorpay',razorpayOrder.id,orders[0].total,'created',JSON.stringify(razorpayOrder)]);res.json({keyId:process.env.RAZORPAY_KEY_ID,order:razorpayOrder});}catch(e){next(e)}});
router.post('/payments/razorpay/verify',requireAuth,async(req,res,next)=>{try{const {orderId,razorpayOrderId,razorpayPaymentId,razorpaySignature}=req.body;if(!process.env.RAZORPAY_KEY_ID||!process.env.RAZORPAY_KEY_SECRET)return res.status(503).json({message:'Online payment is not configured. Add Razorpay keys to server/.env.'});if(!orderId)return res.status(400).json({message:'Order reference is missing'});const [orders]=await pool.query('SELECT id,total,payment_status FROM orders WHERE id=? AND user_id=? LIMIT 1',[orderId,req.user.id]);if(!orders.length)return res.status(404).json({message:'Order not found'});if(orders[0].payment_status==='Paid')return res.json({message:'Payment already verified',orderId});const [payments]=await pool.query("SELECT provider_order_id,provider_payment_id FROM payments WHERE order_id=? AND provider='Razorpay' ORDER BY id DESC LIMIT 1",[orderId]);if(!payments.length||!payments[0].provider_order_id)return res.status(400).json({message:'Razorpay order reference was not found. Start payment again from this order.'});const providerOrderId=payments[0].provider_order_id;if(razorpayOrderId&&razorpayOrderId!==providerOrderId)return res.status(400).json({message:'This payment does not belong to the selected order'});const providerAuth=Buffer.from(`${process.env.RAZORPAY_KEY_ID}:${process.env.RAZORPAY_KEY_SECRET}`).toString('base64');let paymentId=razorpayPaymentId;let providerPayment;const listResponse=await fetch(`https://api.razorpay.com/v1/orders/${encodeURIComponent(providerOrderId)}/payments`,{headers:{Authorization:`Basic ${providerAuth}`}});const paymentList=await listResponse.json();if(!listResponse.ok)return res.status(502).json({message:`Razorpay payment lookup failed: ${paymentList.error?.description||'provider returned an error'}`});if(paymentId){const listedPayment=(paymentList.items||[]).find((payment)=>payment.id===paymentId);if(!listedPayment)return res.status(400).json({message:'The Razorpay payment was not created for this order.'});providerPayment=listedPayment;}else{providerPayment=(paymentList.items||[]).find((payment)=>payment.status==='captured')||paymentList.items?.[0];paymentId=providerPayment?.id;}if(!paymentId)return res.status(400).json({message:'Razorpay has not returned a payment reference yet. Check the order again in a moment.'});const expected=razorpaySignature?crypto.createHmac('sha256',process.env.RAZORPAY_KEY_SECRET).update(`${providerOrderId}|${paymentId}`).digest('hex'):null;const signatureMatches=!razorpaySignature||(expected.length===razorpaySignature.length&&crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(razorpaySignature)));if(!signatureMatches)return res.status(400).json({message:'Razorpay signature mismatch. The payment was not confirmed for this order.'});const providerResponse=await fetch(`https://api.razorpay.com/v1/payments/${encodeURIComponent(paymentId)}`,{headers:{Authorization:`Basic ${providerAuth}`}});providerPayment=await providerResponse.json();if(!providerResponse.ok)return res.status(502).json({message:`Razorpay payment lookup failed: ${providerPayment.error?.description||'provider returned an error'}`});if(providerPayment.order_id&&providerPayment.order_id!==providerOrderId)return res.status(400).json({message:'The Razorpay payment was created for a different order.'});if(Number(providerPayment.amount)!==Math.round(Number(orders[0].total)*100))return res.status(400).json({message:'Razorpay payment amount does not match this order.'});if(providerPayment.currency!=='INR')return res.status(400).json({message:'Razorpay payment currency does not match this order.'});if(providerPayment.status!=='captured')return res.status(409).json({message:`Payment is ${providerPayment.status}. The order will be dispatched after Razorpay marks it captured.`});await tx(async(conn)=>{await conn.query("UPDATE payments SET provider_payment_id=?,status='paid',raw_reference=? WHERE order_id=? AND provider='Razorpay'",[paymentId,JSON.stringify(providerPayment),orderId]);await conn.query("UPDATE orders SET payment_status='Paid',order_status='Processing' WHERE id=? AND payment_status<>'Paid'",[orderId]);await conn.query("INSERT INTO order_status_history(order_id,new_status,note,changed_by) VALUES(?,?,?,?)",[orderId,'Processing','Razorpay payment captured and verified',req.user.id]);});res.json({message:'Payment verified and order placed',orderId,status:'Paid'});}catch(e){next(e)}});
router.get('/me/wishlist',requireAuth,async(req,res,next)=>{try{const [r]=await pool.query('SELECT w.id,p.*, (SELECT image_url FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.display_order,pi.id LIMIT 1) image_url FROM wishlist_items w JOIN products p ON p.id=w.product_id WHERE w.user_id=? ORDER BY w.created_at DESC',[req.user.id]);res.json({items:r})}catch(e){next(e)}});
router.post('/me/wishlist/:productId',requireAuth,async(req,res,next)=>{try{await pool.query('INSERT IGNORE INTO wishlist_items(user_id,product_id) VALUES(?,?)',[req.user.id,req.params.productId]);res.json({message:'Added to wishlist'});}catch(e){next(e)}});
router.delete('/me/wishlist/:productId',requireAuth,async(req,res,next)=>{try{await pool.query('DELETE FROM wishlist_items WHERE user_id=? AND product_id=?',[req.user.id,req.params.productId]);res.json({message:'Removed from wishlist'});}catch(e){next(e)}});
router.post('/me/cart',requireAuth,async(req,res,next)=>{try{const {productId,variantId,quantity}=req.body;const qty=Math.max(1,Number(quantity||1));const [v]=await pool.query('SELECT id,stock_quantity FROM product_variants WHERE product_id=? AND active=1 AND stock_quantity>0 ORDER BY (id=?) DESC,id LIMIT 1',[productId,variantId]);if(!v.length)return res.status(400).json({message:'This product is currently out of stock'});if(qty>v[0].stock_quantity)return res.status(400).json({message:'Requested quantity is not available'});await pool.query(`INSERT INTO cart_items(user_id,product_id,variant_id,quantity) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE quantity=LEAST(quantity+VALUES(quantity),?)`,[req.user.id,productId,v[0].id,qty,v[0].stock_quantity]);res.json({message:'Added to cart'});}catch(e){next(e)}});
router.get('/me/cart',requireAuth,async(req,res,next)=>{try{const [r]=await pool.query(`SELECT ci.id,ci.quantity,ci.variant_id,p.id product_id,p.name,p.slug,p.price,p.sale_price,v.size,v.color,v.stock_quantity,(SELECT image_url FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.display_order,pi.id LIMIT 1) image_url FROM cart_items ci JOIN products p ON p.id=ci.product_id LEFT JOIN product_variants v ON v.id=ci.variant_id WHERE ci.user_id=?`,[req.user.id]);res.json({items:r})}catch(e){next(e)}});
router.put('/me/cart/:id',requireAuth,async(req,res,next)=>{try{const qty=Math.max(1,Number(req.body.quantity));const [x]=await pool.query(`SELECT ci.id,v.stock_quantity FROM cart_items ci JOIN product_variants v ON v.id=ci.variant_id WHERE ci.id=? AND ci.user_id=?`,[req.params.id,req.user.id]);if(!x.length)return res.status(404).json({message:'Cart item not found'});if(qty>x[0].stock_quantity)return res.status(400).json({message:'Insufficient stock'});await pool.query('UPDATE cart_items SET quantity=? WHERE id=? AND user_id=?',[qty,req.params.id,req.user.id]);res.json({message:'Cart updated'});}catch(e){next(e)}});
router.delete('/me/cart/:id',requireAuth,async(req,res,next)=>{try{await pool.query('DELETE FROM cart_items WHERE id=? AND user_id=?',[req.params.id,req.user.id]);res.json({message:'Removed'});}catch(e){next(e)}});

router.post('/orders',requireAuth,async(req,res,next)=>{
  try {
    const {shipping={},couponCode}=req.body||{};
    const idempotencyKey=String(req.get('Idempotency-Key')||req.get('X-Idempotency-Key')||'').trim();
    if(!idempotencyKey||idempotencyKey.length>100)return res.status(400).json({message:'A valid idempotency key is required'});
    const [[existing]]=await pool.query('SELECT id,order_code,total FROM orders WHERE user_id=? AND idempotency_key=? LIMIT 1',[req.user.id,idempotencyKey]);
    if(existing)return res.status(200).json({id:existing.id,orderCode:existing.order_code,total:existing.total,duplicate:true});
    const result=await tx(async(conn)=>{
      const [[lockedExisting]]=await conn.query('SELECT id,order_code,total FROM orders WHERE user_id=? AND idempotency_key=? FOR UPDATE',[req.user.id,idempotencyKey]);
      if(lockedExisting)return {id:lockedExisting.id,orderCode:lockedExisting.order_code,total:lockedExisting.total,duplicate:true};
      const [items]=await conn.query(`SELECT ci.*,p.name,p.sku,p.price,p.sale_price,v.size,v.color,v.stock_quantity,v.sku variant_sku FROM cart_items ci JOIN products p ON p.id=ci.product_id LEFT JOIN product_variants v ON v.id=ci.variant_id WHERE ci.user_id=? FOR UPDATE`,[req.user.id]);
      if(!items.length)throw Object.assign(new Error('Cart is empty'),{status:400});
      let subtotal=0;
      for(const item of items){if(!item.stock_quantity||item.quantity>item.stock_quantity)throw Object.assign(new Error(`Insufficient stock for ${item.name}`),{status:400});subtotal+=Number(item.sale_price||item.price)*item.quantity;}
      let discount=0;let coupon=null;
      if(couponCode){const [cr]=await conn.query('SELECT * FROM coupons WHERE code=? AND active=1 LIMIT 1',[String(couponCode).trim().toUpperCase()]);if(!cr.length)throw Object.assign(new Error('Invalid coupon'),{status:400});coupon=cr[0];if(coupon.expires_at&&new Date(coupon.expires_at)<new Date())throw Object.assign(new Error('Coupon has expired'),{status:400});if(subtotal<Number(coupon.min_order_value))throw Object.assign(new Error('Minimum order value not reached'),{status:400});discount=coupon.type==='PERCENTAGE'?subtotal*Number(coupon.value)/100:Number(coupon.value);if(coupon.max_discount)discount=Math.min(discount,Number(coupon.max_discount));}
      const [settingRows]=await conn.query("SELECT `key`,`value` FROM store_settings WHERE `key` IN ('shipping_flat_rate','free_shipping_threshold')");
      const settings=Object.fromEntries(settingRows.map((row)=>[row.key,row.value]));const shippingAmount=subtotal-discount>=Number(settings.free_shipping_threshold||0)?0:Number(settings.shipping_flat_rate||0);const total=Math.max(0,subtotal-discount+shippingAmount);const code=orderCode();
      const [or]=await conn.query(`INSERT INTO orders(order_code,idempotency_key,user_id,subtotal,discount,shipping,total,coupon_code,payment_status,order_status,shipping_name,shipping_email,shipping_mobile,shipping_address,shipping_city,shipping_state,shipping_postal_code,shipping_country) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,[code,idempotencyKey,req.user.id,subtotal,discount,shippingAmount,total,couponCode||null,'Pending','Payment Pending',shipping.name,shipping.email,shipping.mobile,shipping.address,shipping.city,shipping.state,shipping.postalCode,shipping.country||'India']);
      for(const item of items){const unit=Number(item.sale_price||item.price);await conn.query('INSERT INTO order_items(order_id,product_id,variant_id,product_name,sku,size,color,quantity,unit_price,subtotal) VALUES(?,?,?,?,?,?,?,?,?,?)',[or.insertId,item.product_id,item.variant_id,item.name,item.variant_sku||item.sku,item.size,item.color,item.quantity,unit,unit*item.quantity]);await conn.query('UPDATE product_variants SET stock_quantity=stock_quantity-? WHERE id=? AND stock_quantity>=?',[item.quantity,item.variant_id,item.quantity]);}
      await conn.query('INSERT INTO order_status_history(order_id,new_status,note,changed_by) VALUES(?,?,?,?)',[or.insertId,'Payment Pending','Order created; awaiting payment confirmation',req.user.id]);if(coupon)await conn.query('UPDATE coupons SET used_count=used_count+1 WHERE id=?',[coupon.id]);await conn.query('DELETE FROM cart_items WHERE user_id=?',[req.user.id]);return {id:or.insertId,orderCode:code,total};
    });
    res.status(result.duplicate?200:201).json(result);
  }catch(e){if(e.code==='ER_DUP_ENTRY'&&String(e.sqlMessage||'').includes('idempotency_key')){const [[order]]=await pool.query('SELECT id,order_code,total FROM orders WHERE user_id=? AND idempotency_key=? LIMIT 1',[req.user.id,String(req.get('Idempotency-Key')||req.get('X-Idempotency-Key')||'')]);if(order)return res.status(200).json({id:order.id,orderCode:order.order_code,total:order.total,duplicate:true});}next(e)}
});

// Admin APIs
router.use('/admin',requireAuth,requireAdmin);
router.get('/admin/orders/:id/invoice',async(req,res,next)=>sendInvoice(req,res,next,true));
router.get('/admin/stats',async(_,res,next)=>{try{const [[p],[c],[o],[po],[a],[pa],[low]] = await Promise.all([
 pool.query('SELECT COUNT(*) total FROM products'),pool.query("SELECT COUNT(*) total FROM users WHERE role='USER'"),pool.query('SELECT COUNT(*) total FROM orders'),pool.query("SELECT COUNT(*) total FROM orders WHERE order_status IN ('Pending','Payment Pending','Processing')"),pool.query('SELECT COUNT(*) total FROM applications'),pool.query("SELECT COUNT(*) total FROM applications WHERE status IN ('Submitted','Under Review','More Information Required')"),pool.query('SELECT COUNT(*) total FROM product_variants WHERE stock_quantity<5')]);res.json({products:p[0].total,customers:c[0].total,orders:o[0].total,pendingOrders:po[0].total,applications:a[0].total,pendingApplications:pa[0].total,lowStock:low[0].total});}catch(e){next(e)}});
router.get('/admin/products',async(_,res,next)=>{try{const [products]=await pool.query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC');for(const p of products){const [i]=await pool.query('SELECT * FROM product_images WHERE product_id=? ORDER BY display_order,id',[p.id]);const [v]=await pool.query('SELECT * FROM product_variants WHERE product_id=? ORDER BY id',[p.id]);p.images=i;p.variants=v;}res.json({products});}catch(e){next(e)}});
router.post('/admin/products',async(req,res,next)=>{try{const p=req.body;const slug=slugify(p.name);const [r]=await pool.query(`INSERT INTO products(category_id,name,slug,sku,description,short_description,price,sale_price,material,care_instructions,shipping_information,return_information,tags,featured,new_arrival,best_seller,offer,active,display_order,seo_title,seo_description) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,[p.categoryId||null,p.name,slug,p.sku,p.description||null,p.shortDescription||null,Number(p.price),p.salePrice?Number(p.salePrice):null,p.material||null,p.careInstructions||null,p.shippingInformation||null,p.returnInformation||null,JSON.stringify(p.tags||[]),!!p.featured,!!p.newArrival,!!p.bestSeller,!!p.offer,p.active!==false,Number(p.displayOrder||0),p.seoTitle||null,p.seoDescription||null]);for(const im of productImages(p))await pool.query('INSERT INTO product_images(product_id,image_url,alt_text,display_order) VALUES(?,?,?,?)',[r.insertId,im.imageUrl,im.altText||p.name,im.displayOrder||0]);for(const v of productVariants(p))await pool.query('INSERT INTO product_variants(product_id,size,color,sku,price_override,sale_price_override,stock_quantity,active) VALUES(?,?,?,?,?,?,?,?)',[r.insertId,v.size,v.color,v.sku,v.priceOverride||null,v.salePriceOverride||null,Number(v.stockQuantity||0),v.active!==false]);res.status(201).json({id:r.insertId});}catch(e){next(e)}});
router.put('/admin/products/:id',async(req,res,next)=>{try{const p=req.body;const slug=slugify(p.name);await tx(async(conn)=>{await conn.query(`UPDATE products SET category_id=?,name=?,slug=?,sku=?,description=?,short_description=?,price=?,sale_price=?,material=?,care_instructions=?,shipping_information=?,return_information=?,tags=?,featured=?,new_arrival=?,best_seller=?,offer=?,active=?,display_order=?,seo_title=?,seo_description=? WHERE id=?`,[p.categoryId||null,p.name,slug,p.sku,p.description||null,p.shortDescription||null,Number(p.price),p.salePrice?Number(p.salePrice):null,p.material||null,p.careInstructions||null,p.shippingInformation||null,p.returnInformation||null,JSON.stringify(p.tags||[]),!!p.featured,!!p.newArrival,!!p.bestSeller,!!p.offer,p.active!==false,Number(p.displayOrder||0),p.seoTitle||null,p.seoDescription||null,p.id]);await conn.query('DELETE FROM product_images WHERE product_id=?',[p.id]);for(const im of p.images||[])if(im.imageUrl)await conn.query('INSERT INTO product_images(product_id,image_url,alt_text,display_order) VALUES(?,?,?,?)',[p.id,im.imageUrl,im.altText||p.name,Number(im.displayOrder||0)]);await conn.query('DELETE FROM product_variants WHERE product_id=?',[p.id]);for(const v of p.variants||[])await conn.query('INSERT INTO product_variants(product_id,size,color,sku,price_override,sale_price_override,stock_quantity,active) VALUES(?,?,?,?,?,?,?,?)',[p.id,v.size,v.color,v.sku,v.priceOverride||null,v.salePriceOverride||null,Number(v.stockQuantity||0),v.active!==false]);});res.json({message:'Product updated'});}catch(e){next(e)}});
