router.put('/admin/reviews/:id',async(req,res,next)=>{try{const {userId,customerName,rating,reviewText,imageUrl,status,displayOrder}=req.body;if(!String(customerName||'').trim()||!String(reviewText||'').trim()||Number(rating)<1||Number(rating)>5)return res.status(400).json({message:'Customer, rating from 1 to 5, and review content are required'});await pool.query('UPDATE reviews SET user_id=?,customer_name=?,rating=?,review_text=?,image_url=?,status=?,display_order=? WHERE id=?',[userId||null,customerName.trim(),Number(rating),reviewText.trim(),imageUrl||null,status||'Pending',Number(displayOrder||0),req.params.id]);res.json({message:'Review updated'});}catch(e){next(e)}});
