router.post('/admin/media',upload.single('file'),async(req,res,next)=>{try{if(!req.file)return res.status(400).json({message:'File is required'});const url=`/uploads/${req.file.filename}`;const [r]=await pool.query('INSERT INTO media_library(file_url,original_name,mime_type,size_bytes,alt_text) VALUES(?,?,?,?,?)',[url,req.file.originalname,req.file.mimetype,req.file.size,req.body.altText||null]);res.status(201).json({id:r.insertId,fileUrl:url});}catch(e){next(e)}});
